    height = bottom - top
    # Both demonstrations are rectangular outlines with five occupied rows.
    # The top and bottom bars move to the left/top and stay at the base;
    # vertical sides become separated diagonal traces.
    if height == 4:
        output_rows = [
            [left-2, left-1, left],
            [left-1, left+1],
            [left-2, left+2],
            [left-1, left+3],
